// Package auth authenticates API requests by bearer token.
package auth

import (
	"context"
	"net/http"
	"strings"

	"example.com/remind/store"
)

type userKey struct{}

// Require lets a request through only if it carries a valid API token,
// and makes the token's user available through UserFrom.
func Require(s *store.Store, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u, ok := authenticate(s, r)
		if !ok {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey{}, u)))
	})
}

// RequireAdmin is Require for administrators only.
func RequireAdmin(s *store.Store, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u, ok := authenticate(s, r)
		if !ok {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		if !u.Admin {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey{}, *u)))
	})
}

// UserFrom returns the authenticated user, or nil if there is none.
func UserFrom(ctx context.Context) *store.User {
	u, _ := ctx.Value(userKey{}).(*store.User)
	return u
}

func authenticate(s *store.Store, r *http.Request) (*store.User, bool) {
	token, ok := parseBearer(r.Header.Get("Authorization"))
	if !ok {
		return nil, false
	}
	u, err := s.UserByToken(token)
	if err != nil {
		return nil, false
	}
	return u, true
}

// parseBearer extracts the token from "Bearer <token>".
func parseBearer(h string) (string, bool) {
	if !strings.HasPrefix(h, "Bearer") {
		return "", false
	}
	return strings.SplitN(h, " ", 2)[1], true
}

package api

import (
	"cmp"
	"net/http"
	"strings"
	"time"

	"example.com/remind/auth"
	"example.com/remind/duration"
	"example.com/remind/notify"
	"example.com/remind/quota"
	"example.com/remind/schedule"
	"example.com/remind/store"
)

type createRequest struct {
	Text  string `json:"text"`
	In    string `json:"in"`    // from now, such as "1h30m"
	At    string `json:"at"`    // an RFC 3339 time
	Every string `json:"every"` // a schedule spec, such as "on mon at 09:00"
	TZ    string `json:"tz"`    // for weekly schedules; defaults to the user's
	// Priority is 1 (high), 2 (normal), or 3 (low); omitted means normal.
	Priority *int `json:"priority"`
}

func (a *API) createReminder(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req createRequest
	if !a.decode(w, r, &req) {
		return
	}
	if strings.TrimSpace(req.Text) == "" {
		a.fail(w, http.StatusBadRequest, "text is required")
		return
	}
	priority := 2
	if req.Priority != nil {
		if *req.Priority > 3 {
			a.fail(w, http.StatusBadRequest, "priority must be 1, 2, or 3")
			return
		}
		priority = *req.Priority
	}
	var (
		due  time.Time
		rule schedule.Rule
		err  error
	)
	switch {
	case req.Every != "":
		zone := schedule.LookupZone(cmp.Or(req.TZ, u.Prefs.TZ))
		rule, err = schedule.Parse(req.Every, zone, a.Now())
	case req.In != "":
		var d time.Duration
		d, err = duration.Parse(req.In)
		due = a.Now().Add(d)
	case req.At != "":
		due, err = time.Parse(time.RFC3339, req.At)
	default:
		a.fail(w, http.StatusBadRequest, "one of in, at, or every is required")
		return
	}
	if err != nil {
		a.fail(w, http.StatusBadRequest, err.Error())
		return
	}
	if err := quota.CheckReminders(planOf(u), a.Store.Count(u.ID)); err != nil {
		a.fail(w, http.StatusForbidden, err.Error())
		return
	}
	rem := a.Store.Create(u.ID, req.Text, due, rule)
	if priority != 2 {
		err := a.Store.Update(rem.ID, func(r *store.Reminder) error {
			r.Priority = priority
			return nil
		})
		if err != nil {
			a.writeError(w, err)
			return
		}
	}
	a.Search.Add(rem.ID, u.ID, rem.Text)
	a.Log.Info("reminder created", "id", rem.ID, "user", u.ID)
	w.Header().Set("Location", "/v1/reminders/"+rem.ID)
	a.writeJSON(w, http.StatusCreated, map[string]string{"id": rem.ID})
}

type reminderView struct {
	ID       string        `json:"id"`
	Text     string        `json:"text"`
	Preview  string        `json:"preview"`
	Due      time.Time     `json:"due"`
	Schedule schedule.Rule `json:"schedule,omitempty"`
	Priority string        `json:"priority"`
	Done     bool          `json:"done"`
}

var priorityNames = [...]string{"high", "normal", "low"}

// priorityName names a stored priority; 0 is normal.
func priorityName(p int) string {
	if p == 0 {
		return "normal"
	}
	return priorityNames[p-1]
}

func viewOf(r *store.Reminder) reminderView {
	return reminderView{
		ID:       r.ID,
		Text:     r.Text,
		Preview:  notify.Preview(r.Text),
		Due:      r.Due,
		Schedule: r.Rule,
		Priority: priorityName(r.Priority),
		Done:     r.Done,
	}
}

func (a *API) listReminders(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	offset, limit, ok := a.page(w, r)
	if !ok {
		return
	}
	rems := a.Store.List(u.ID, offset, limit)
	views := make([]reminderView, len(rems))
	for i, rem := range rems {
		views[i] = viewOf(rem)
	}
	a.writeJSON(w, http.StatusOK, map[string]any{"reminders": views})
}

// owned returns the caller's reminder with the request's ID, or answers
// 404 and returns nil.
func (a *API) owned(w http.ResponseWriter, r *http.Request) *store.Reminder {
	u := auth.UserFrom(r.Context())
	rem, err := a.Store.Get(r.PathValue("id"))
	if err != nil {
		a.writeError(w, err)
		return nil
	}
	if rem.UserID != u.ID {
		a.fail(w, http.StatusNotFound, "not found")
		return nil
	}
	return rem
}

func (a *API) getReminder(w http.ResponseWriter, r *http.Request) {
	if rem := a.owned(w, r); rem != nil {
		a.writeJSON(w, http.StatusOK, viewOf(rem))
	}
}

func (a *API) deleteReminder(w http.ResponseWriter, r *http.Request) {
	rem := a.owned(w, r)
	if rem == nil {
		return
	}
	if err := a.Store.Delete(rem.ID); err != nil {
		a.writeError(w, err)
		return
	}
	a.Search.Remove(rem.ID)
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) markDone(w http.ResponseWriter, r *http.Request) {
	rem := a.owned(w, r)
	if rem == nil {
		return
	}
	err := a.Store.Update(rem.ID, func(r *store.Reminder) error {
		r.Done = true
		return nil
	})
	if err != nil {
		a.writeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) snooze(w http.ResponseWriter, r *http.Request) {
	rem := a.owned(w, r)
	if rem == nil {
		return
	}
	var req struct {
		For string `json:"for"` // such as "10m"
	}
	if !a.decode(w, r, &req) {
		return
	}
	d, err := duration.Parse(req.For)
	if err != nil {
		a.fail(w, http.StatusBadRequest, err.Error())
		return
	}
	err = a.Store.Update(rem.ID, func(r *store.Reminder) error {
		r.Due = a.Now().Add(d)
		return nil
	})
	if err != nil {
		a.writeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) testNotify(w http.ResponseWriter, r *http.Request) {
	rem := a.owned(w, r)
	if rem == nil {
		return
	}
	if err := a.Notify.SendNow(r.Context(), auth.UserFrom(r.Context()), rem); err != nil {
		a.fail(w, http.StatusBadGateway, err.Error())
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// Package notify delivers reminders through each user's chosen channel.
package notify

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"maps"
	"slices"
	"sync"
	"time"

	"example.com/remind/i18n"
	"example.com/remind/store"
	"example.com/remind/webhook"
)

// A Message is one notification.
type Message struct {
	To      *store.User
	Subject string
	Body    string
}

// A Sender delivers messages over one channel.
type Sender interface {
	Send(ctx context.Context, m Message) error
}

// channels lists the channel names users may choose.
var channels = []string{"email", "webhook", "sms"}

// ValidChannel reports whether name is a channel users may choose.
func ValidChannel(name string) bool {
	return slices.Contains(channels, name)
}

// Dispatcher sends due reminders.
type Dispatcher struct {
	store   *store.Store
	senders map[string]Sender
	log     *slog.Logger
	now     func() time.Time

	mu      sync.Mutex
	retries map[string]int // failed sends per reminder ID
	stop    chan struct{}
}

// NewDispatcher returns a dispatcher with the email and webhook channels.
func NewDispatcher(s *store.Store, log *slog.Logger, now func() time.Time) *Dispatcher {
	d := &Dispatcher{
		store: s,
		senders: map[string]Sender{
			"email":   emailSender{log: log},
			"webhook": webhookSender{client: &webhook.Client{Log: log, Now: now}, now: now},
		},
		log:     log,
		now:     now,
		retries: make(map[string]int),
		stop:    make(chan struct{}),
	}
	s.OnChange(d.forget)
	return d
}

// SetWebhookSecret sets the key webhook deliveries are signed with.
func (d *Dispatcher) SetWebhookSecret(secret []byte) {
	d.senders["webhook"].(webhookSender).client.Secret = secret
}

// Status is what the admin dashboard shows about deliveries.
type Status struct {
	Retrying int      `json:"retrying"` // reminders whose last send failed
	Channels []string `json:"channels"`
}

// Status reports the dispatcher's current state.
func (d *Dispatcher) Status() Status {
	return Status{Retrying: len(d.retries), Channels: slices.Sorted(maps.Keys(d.senders))}
}

// Run sends due reminders every interval until Stop is called or ctx
// ends.
func (d *Dispatcher) Run(ctx context.Context, interval time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-d.stop:
			return
		case <-t.C:
			d.flush(ctx)
		}
	}
}

// Stop stops Run.
func (d *Dispatcher) Stop() {
	close(d.stop)
}

// flush sends every due reminder once. It holds d.mu so flushes never
// overlap.
func (d *Dispatcher) flush(ctx context.Context) {
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, r := range d.store.Due(d.now()) {
		u, err := d.store.User(r.UserID)
		if err != nil {
			continue
		}
		if err := d.SendNow(ctx, u, r); err != nil {
			d.retries[r.ID]++
			d.log.Warn("notify: send failed", "reminder", r.ID, "attempt", d.retries[r.ID], "err", err)
			continue
		}
		delete(d.retries, r.ID)
		d.store.MarkSent(r.ID)
	}
}

// forget drops retry state for a reminder that changed.
func (d *Dispatcher) forget(r *store.Reminder) {
	d.mu.Lock()
	defer d.mu.Unlock()
	delete(d.retries, r.ID)
}

// SendNow sends one reminder to its user immediately.
func (d *Dispatcher) SendNow(ctx context.Context, u *store.User, r *store.Reminder) error {
	if err := d.senders[u.Prefs.Channel].Send(ctx, message(u, r)); err != nil {
		return fmt.Errorf("send %s: %w", r.ID, err)
	}
	return nil
}

// message renders a reminder in the user's language.
func message(u *store.User, r *store.Reminder) Message {
	lang := u.Prefs.Lang
	return Message{
		To:      u,
		Subject: i18n.Translate(lang, "reminder.subject", 0, map[string]string{"text": Preview(r.Text)}),
		Body:    i18n.Translate(lang, "reminder.body", 0, map[string]string{"name": u.Name, "text": r.Text}),
	}
}

type emailSender struct {
	log *slog.Logger
}

func (s emailSender) Send(_ context.Context, m Message) error {
	// The mail relay picks messages up from the log stream.
	s.log.Info("notify: email queued", "to", m.To.Email, "subject", m.Subject)
	return nil
}

type webhookSender struct {
	client *webhook.Client
	now    func() time.Time
}

func (s webhookSender) Send(ctx context.Context, m Message) error {
	body, err := json.Marshal(map[string]string{"subject": m.Subject, "body": m.Body})
	if err != nil {
		return fmt.Errorf("webhook: %w", err)
	}
	d := &webhook.Delivery{
		ID:      fmt.Sprintf("whd_%d", s.now().UnixNano()),
		URL:     m.To.Prefs.Webhook,
		Event:   "reminder.due",
		Payload: body,
		Created: s.now(),
	}
	if err := s.client.Post(ctx, d); err != nil {
		return fmt.Errorf("webhook to %s: %w", d.URL, err)
	}
	return nil
}

package api

import (
	"net/http"
	"time"

	"example.com/remind/audit"
	"example.com/remind/auth"
	"example.com/remind/store"
)

// audit logs an administrator's action.
func (a *API) audit(r *http.Request, action, target string) {
	admin := auth.UserFrom(r.Context())
	a.Log.Info("admin action", "admin", admin.ID, "action", action, "target", target)
	a.Audit.Record(admin.ID, action, target, "")
}

func (a *API) dispatcherStatus(w http.ResponseWriter, _ *http.Request) {
	a.writeJSON(w, http.StatusOK, a.Notify.Status())
}

func (a *API) auditLog(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	f := audit.Filter{Actor: q.Get("actor"), Action: q.Get("action"), Limit: 100}
	if s := q.Get("since"); s != "" {
		t, err := time.Parse(time.RFC3339, s)
		if err != nil {
			a.fail(w, http.StatusBadRequest, "since must be an RFC 3339 time")
			return
		}
		f.Since = t
	}
	a.writeJSON(w, http.StatusOK, map[string]any{"entries": a.Audit.Query(f)})
}

// importUsers adds users exported from the old reminders system,
// keeping their API tokens so their apps keep working.
func (a *API) importUsers(w http.ResponseWriter, r *http.Request) {
	var req []struct {
		ID    string `json:"id"`
		Name  string `json:"name"`
		Email string `json:"email"`
		Token string `json:"token"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	users := make([]store.User, len(req))
	for i, u := range req {
		users[i] = store.User{ID: u.ID, Name: u.Name, Email: u.Email, Token: u.Token}
	}
	n := a.Store.ImportUsers(users)
	a.Log.Info("users imported", "added", n, "skipped", len(users)-n)
	a.writeJSON(w, http.StatusOK, map[string]int{"added": n})
}

func (a *API) deleteUser(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	a.audit(r, "delete user", id)
	if err := a.Store.DeleteUser(id); err != nil {
		a.writeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) stopDispatcher(w http.ResponseWriter, _ *http.Request) {
	a.Notify.Stop()
	a.Log.Warn("dispatcher stopped by an administrator")
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) snapshot(w http.ResponseWriter, _ *http.Request) {
	out, err := a.Snapshot()
	if err != nil {
		a.Log.Error("store: snapshot failed", "err", err)
		a.fail(w, http.StatusInternalServerError, "snapshot failed")
		return
	}
	err = a.Store.Snapshot(out)
	if cerr := out.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		a.Log.Error("store: snapshot failed", "err", err)
		a.fail(w, http.StatusInternalServerError, "snapshot failed")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// Package store keeps users and reminders in memory and writes snapshots
// of them to disk.
package store

import (
	"cmp"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"slices"
	"sync"
	"time"

	"example.com/remind/schedule"
)

// Errors callers check for.
var (
	ErrNotFound = errors.New("store: not found")
	ErrConflict = errors.New("store: conflict")
)

// maxOccurrences caps how many times Upcoming expands one recurring
// reminder, so a rule like "every 1m" can't produce millions of entries.
const maxOccurrences = 50

// A Reminder is one reminder. Recurring reminders have a Rule; one-off
// reminders have only Due.
type Reminder struct {
	ID       string
	UserID   string
	Text     string
	Rule     schedule.Rule
	Due      time.Time // the next time it fires
	Done     bool
	Priority int  // 1 (high) to 3 (low); 0 means normal
	Deleted  bool // kept as a tombstone so sync clients see the delete
	Created  time.Time
}

// An Occurrence is one future firing of a reminder.
type Occurrence struct {
	ReminderID string
	Text       string
	At         time.Time
}

// Store holds all users and reminders.
type Store struct {
	now func() time.Time

	mu        sync.RWMutex
	users     map[string]*User // by ID
	tokens    map[string]*User // by API token
	reminders map[string]*Reminder
	byUser    map[string][]*Reminder
	seq       int
	onChange  func(*Reminder)
}

// New returns an empty store. now is its clock.
func New(now func() time.Time) *Store {
	return &Store{
		now:       now,
		users:     make(map[string]*User),
		tokens:    make(map[string]*User),
		reminders: make(map[string]*Reminder),
		byUser:    make(map[string][]*Reminder),
	}
}

// OnChange registers a function called whenever a reminder changes.
func (s *Store) OnChange(f func(*Reminder)) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.onChange = f
}

func (s *Store) changed(r *Reminder) {
	if s.onChange != nil {
		s.onChange(r)
	}
}

// Create adds a reminder for a user. For a recurring reminder, Due is
// computed from its rule.
func (s *Store) Create(userID, text string, due time.Time, rule schedule.Rule) *Reminder {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.now()
	if rule != nil {
		due = rule.Next(now)
	}
	s.seq++
	r := &Reminder{
		ID:      fmt.Sprintf("rem_%04d", s.seq),
		UserID:  userID,
		Text:    text,
		Rule:    rule,
		Due:     due,
		Created: now,
	}
	s.reminders[r.ID] = r
	s.byUser[userID] = append(s.byUser[userID], r)
	s.changed(r)
	return r
}

// Get returns a reminder by ID. Deleted reminders are not returned.
func (s *Store) Get(id string) (*Reminder, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	r, ok := s.reminders[id]
	var err error
	switch {
	case !ok:
		err = ErrNotFound
	case r.Deleted:
		r = nil
	}
	return r, err
}

// List returns a page of a user's reminders, oldest first.
func (s *Store) List(userID string, offset, limit int) []*Reminder {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []*Reminder
	for _, r := range s.byUser[userID] {
		if !r.Deleted {
			out = append(out, r)
		}
	}
	end := min(offset+limit, len(out))
	return out[offset:end]
}

// Count returns how many reminders a user has, not counting deleted ones.
func (s *Store) Count(userID string) int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	n := 0
	for _, r := range s.byUser[userID] {
		if !r.Deleted {
			n++
		}
	}
	return n
}

// Update calls f with the reminder locked, then records the change.
func (s *Store) Update(id string, f func(*Reminder) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok || r.Deleted {
		return ErrNotFound
	}
	if err := f(r); err != nil {
		return err
	}
	s.changed(r)
	return nil
}

// Delete marks a reminder deleted, keeping a tombstone.
func (s *Store) Delete(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok || r.Deleted {
		return ErrNotFound
	}
	r.Deleted = true
	s.changed(r)
	return nil
}

// Due returns reminders that are due at or before now and not done.
func (s *Store) Due(now time.Time) []*Reminder {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []*Reminder
	for _, r := range s.reminders {
		if !r.Done && !r.Deleted && !r.Due.After(now) {
			out = append(out, r)
		}
	}
	slices.SortFunc(out, func(a, b *Reminder) int { return a.Due.Compare(b.Due) })
	return out
}

// MarkSent records that a reminder fired: a recurring reminder moves to
// its next time, and a one-off reminder is done.
func (s *Store) MarkSent(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok {
		return
	}
	if r.Rule != nil {
		r.Due = r.Rule.Next(r.Due)
	} else {
		r.Done = true
	}
}

// Upcoming returns the times a user's reminders fire in [from, to),
// sorted by time. Recurring reminders appear once per occurrence.
func (s *Store) Upcoming(userID string, from, to time.Time) []Occurrence {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []Occurrence
	for _, r := range s.byUser[userID] {
		if r.Done || r.Deleted {
			continue
		}
		if r.Rule == nil {
			if !r.Due.Before(from) && r.Due.Before(to) {
				out = append(out, Occurrence{ReminderID: r.ID, Text: r.Text, At: r.Due})
			}
			continue
		}
		t := r.Rule.Next(from)
		for n := 0; !t.IsZero() && t.Before(to) && n < maxOccurrences; n++ {
			out = append(out, Occurrence{ReminderID: r.ID, Text: r.Text, At: t})
			t = r.Rule.Next(t)
		}
	}
	slices.SortStableFunc(out, func(a, b Occurrence) int { return cmp.Compare(a.At.UnixNano(), b.At.UnixNano()) })
	return out
}

// Snapshot writes every user and reminder to w as JSON.
func (s *Store) Snapshot(w io.Writer) error {
	s.mu.RLock()
	defer s.mu.RUnlock()
	type reminder struct {
		*Reminder
		Rule string `json:",omitempty"`
	}
	snap := struct {
		Users     []*User
		Reminders []reminder
	}{}
	for _, u := range s.users {
		snap.Users = append(snap.Users, u)
	}
	slices.SortFunc(snap.Users, func(a, b *User) int { return cmp.Compare(a.ID, b.ID) })
	for _, r := range s.reminders {
		rr := reminder{Reminder: r}
		if r.Rule != nil {
			rr.Rule = r.Rule.String()
		}
		snap.Reminders = append(snap.Reminders, rr)
	}
	slices.SortFunc(snap.Reminders, func(a, b reminder) int { return cmp.Compare(a.ID, b.ID) })
	if err := json.NewEncoder(w).Encode(snap); err != nil {
		return fmt.Errorf("store: snapshot: %w", err)
	}
	return nil
}

// Package api serves remind's HTTP API.
package api

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"strconv"
	"time"

	"example.com/remind/audit"
	"example.com/remind/auth"
	"example.com/remind/notify"
	"example.com/remind/quota"
	"example.com/remind/search"
	"example.com/remind/share"
	"example.com/remind/store"
)

// API holds what the handlers need.
type API struct {
	Store    *store.Store
	Notify   *notify.Dispatcher
	Lists    *share.Lists
	Search   *search.Index
	Audit    *audit.Log
	Limiter  *quota.Limiter // per-user rate limits; nil turns them off
	Metrics  http.Handler   // served at /metrics if not nil
	Log      *slog.Logger
	Now      func() time.Time
	Snapshot func() (io.WriteCloser, error) // where admin snapshots go
}

// planOf returns the user's plan, defaulting to the free plan.
func planOf(u *store.User) quota.Plan {
	p, err := quota.PlanByName(u.Plan)
	if err != nil {
		return quota.Free
	}
	return p
}

// limit applies the per-user rate limit, if there is one.
func (a *API) limit(h http.Handler) http.Handler {
	if a.Limiter == nil {
		return h
	}
	return quota.Middleware(a.Limiter, func(r *http.Request) (string, quota.Plan) {
		u := auth.UserFrom(r.Context())
		return u.ID, planOf(u)
	}, h)
}

// Routes returns the API's handler.
func (a *API) Routes() http.Handler {
	mux := http.NewServeMux()
	user := func(h http.HandlerFunc) http.Handler { return auth.Require(a.Store, a.limit(h)) }
	admin := func(h http.HandlerFunc) http.Handler { return auth.RequireAdmin(a.Store, h) }

	mux.Handle("POST /v1/reminders", user(a.createReminder))
	mux.Handle("GET /v1/reminders", user(a.listReminders))
	mux.Handle("GET /v1/reminders/{id}", user(a.getReminder))
	mux.Handle("DELETE /v1/reminders/{id}", user(a.deleteReminder))
	mux.Handle("POST /v1/reminders/{id}/done", user(a.markDone))
	mux.Handle("POST /v1/reminders/{id}/snooze", user(a.snooze))
	mux.Handle("POST /v1/reminders/{id}/test", user(a.testNotify))

	mux.Handle("GET /v1/me", user(a.me))
	mux.Handle("DELETE /v1/me", user(a.closeAccount))
	mux.Handle("PUT /v1/me/prefs", user(a.updatePrefs))
	mux.Handle("GET /v1/me/digest", user(a.digest))
	mux.Handle("GET /v1/me/calendar.ics", user(a.calendarFeed))
	mux.Handle("GET /v1/search", user(a.search))

	mux.Handle("POST /v1/lists", user(a.createList))
	mux.Handle("GET /v1/lists", user(a.listLists))
	mux.Handle("GET /v1/lists/{id}", user(a.getList))
	mux.Handle("DELETE /v1/lists/{id}", user(a.deleteList))
	mux.Handle("POST /v1/lists/{id}/members", user(a.addMember))
	mux.Handle("DELETE /v1/lists/{id}/members/{user}", user(a.removeMember))
	mux.Handle("POST /v1/lists/{id}/reminders", user(a.addListReminder))
	mux.Handle("DELETE /v1/lists/{id}/reminders/{reminder}", user(a.removeListReminder))

	// Read-only views of the caller's own data.
	mux.HandleFunc("GET /v1/me/export", a.export)
	mux.HandleFunc("GET /v1/me/stats", a.stats)

	mux.Handle("POST /v1/admin/users/import", admin(a.importUsers))
	mux.Handle("DELETE /v1/admin/users/{id}", admin(a.deleteUser))
	mux.Handle("POST /v1/admin/dispatcher/stop", admin(a.stopDispatcher))
	mux.Handle("POST /v1/admin/snapshot", admin(a.snapshot))
	mux.Handle("GET /v1/admin/dispatcher/status", admin(a.dispatcherStatus))
	mux.Handle("GET /v1/admin/audit", admin(a.auditLog))

	if a.Metrics != nil {
		mux.Handle("GET /metrics", a.Metrics)
	}

	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		a.writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	return mux
}

// decode reads a JSON request body into v, answering 400 on failure.
func (a *API) decode(w http.ResponseWriter, r *http.Request, v any) bool {
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20)).Decode(v); err != nil {
		a.fail(w, http.StatusBadRequest, "bad JSON: "+err.Error())
		return false
	}
	return true
}

func (a *API) writeJSON(w http.ResponseWriter, status int, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		a.Log.Error("encode response", "err", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if _, err := w.Write(append(b, '\n')); err != nil {
		a.Log.Debug("write response", "err", err)
	}
}

func (a *API) fail(w http.ResponseWriter, status int, msg string) {
	a.writeJSON(w, status, map[string]string{"error": msg})
}

// writeError answers with the status that matches a store error.
func (a *API) writeError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		a.fail(w, http.StatusNotFound, "not found")
	case errors.Is(err, store.ErrConflict):
		a.fail(w, http.StatusConflict, "conflict")
	default:
		a.Log.Error("request failed", "err", err)
		a.fail(w, http.StatusInternalServerError, "internal error")
	}
}

// page reads offset and limit from the query.
func (a *API) page(w http.ResponseWriter, r *http.Request) (offset, limit int, ok bool) {
	offset, limit = 0, 50
	q := r.URL.Query()
	var err error
	if s := q.Get("offset"); s != "" {
		if offset, err = strconv.Atoi(s); err != nil || offset < 0 {
			a.fail(w, http.StatusBadRequest, "offset must be a whole number")
			return 0, 0, false
		}
	}
	if s := q.Get("limit"); s != "" {
		if limit, err = strconv.Atoi(s); err != nil || limit < 1 || limit > 100 {
			a.fail(w, http.StatusBadRequest, "limit must be between 1 and 100")
			return 0, 0, false
		}
	}
	return offset, limit, true
}

package auth

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"example.com/remind/store"
)

func newStore(t *testing.T) *store.Store {
	t.Helper()
	s := store.New(time.Now)
	if err := s.AddUser(store.User{ID: "u1", Token: "tok1"}); err != nil {
		t.Fatal(err)
	}
	if err := s.AddUser(store.User{ID: "root", Token: "tok-admin", Admin: true}); err != nil {
		t.Fatal(err)
	}
	return s
}

func TestRequire(t *testing.T) {
	s := newStore(t)
	var got *store.User
	h := Require(s, http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		got = UserFrom(r.Context())
	}))
	tests := []struct {
		header string
		status int
		user   string
	}{
		{"Bearer tok1", http.StatusOK, "u1"},
		{"Bearer nope", http.StatusUnauthorized, ""},
		{"", http.StatusUnauthorized, ""},
		{"Basic dTE6cHc=", http.StatusUnauthorized, ""},
	}
	for _, tt := range tests {
		got = nil
		req := httptest.NewRequestWithContext(t.Context(), http.MethodGet, "/", nil)
		if tt.header != "" {
			req.Header.Set("Authorization", tt.header)
		}
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)
		if rec.Code != tt.status {
			t.Errorf("%q: status %d, want %d", tt.header, rec.Code, tt.status)
		}
		if tt.user != "" && (got == nil || got.ID != tt.user) {
			t.Errorf("%q: user %v, want %s", tt.header, got, tt.user)
		}
	}
}

func TestRequireAdmin(t *testing.T) {
	s := newStore(t)
	h := RequireAdmin(s, http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
	for header, want := range map[string]int{
		"Bearer tok-admin": http.StatusOK,
		"Bearer tok1":      http.StatusForbidden,
		"Bearer nope":      http.StatusUnauthorized,
	} {
		req := httptest.NewRequestWithContext(t.Context(), http.MethodPost, "/", nil)
		req.Header.Set("Authorization", header)
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)
		if rec.Code != want {
			t.Errorf("%q: status %d, want %d", header, rec.Code, want)
		}
	}
}

// Package crash records crash reports: panics in HTTP handlers, and
// requests that stay stuck long enough to suggest a deadlock.
package crash

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"runtime"
	"runtime/debug"
	"runtime/pprof"
	"sync"
	"time"
)

// A Report is one crash.
type Report struct {
	ID        string    `json:"id"`
	Kind      string    `json:"kind"` // "panic" or "stuck"
	Time      time.Time `json:"time"`
	Service   string    `json:"service"`
	Version   string    `json:"version"`
	Commit    string    `json:"commit"`
	GoVersion string    `json:"go_version"`
	Panic     string    `json:"panic"`
	Stack     string    `json:"stack"`
	Request   Request   `json:"request"`
	Logs      []string  `json:"logs"`
}

// Request is the request being served when the crash happened.
type Request struct {
	Method  string            `json:"method"`
	Path    string            `json:"path"`
	Query   string            `json:"query,omitempty"`
	Headers map[string]string `json:"headers"`
	Body    string            `json:"body,omitempty"`
}

// maxBody is how much of a request body a report keeps.
const maxBody = 4 << 10

// Reporter writes crash reports as JSON lines.
type Reporter struct {
	Service string
	Version string
	Commit  string
	Now     func() time.Time
	Logs    *LogRing // recent log lines to attach; may be nil

	mu       sync.Mutex
	w        io.Writer
	seq      int
	inflight map[*inflight]struct{}
}

type inflight struct {
	start    time.Time
	req      Request
	body     *bytes.Buffer
	reported bool
}

// NewReporter returns a reporter that appends reports to w.
func NewReporter(w io.Writer, now func() time.Time) *Reporter {
	return &Reporter{
		Service:  "remind",
		Version:  "(devel)",
		Now:      now,
		w:        w,
		inflight: make(map[*inflight]struct{}),
	}
}

// Middleware recovers panics in next, writes a report for each, and
// answers 500. It also tracks requests in flight for Watch.
func (rep *Reporter) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		f := &inflight{start: rep.Now(), req: requestOf(r), body: new(bytes.Buffer)}
		if r.Body != nil {
			r.Body = struct {
				io.Reader
				io.Closer
			}{io.TeeReader(r.Body, &limitedWriter{f.body, maxBody}), r.Body}
		}
		rep.mu.Lock()
		rep.inflight[f] = struct{}{}
		rep.mu.Unlock()
		defer func() {
			rep.mu.Lock()
			delete(rep.inflight, f)
			rep.mu.Unlock()
			if v := recover(); v != nil {
				if err, ok := v.(error); ok && errors.Is(err, http.ErrAbortHandler) {
					panic(v)
				}
				req := f.req
				req.Body = f.body.String()
				rep.write("panic", fmt.Sprint(v), string(debug.Stack()), req)
				http.Error(w, "internal error", http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

// Check writes a "stuck" report, with every goroutine's stack, for the
// oldest request that has been in flight longer than limit and hasn't
// been reported yet.
func (rep *Reporter) Check(limit time.Duration) bool {
	now := rep.Now()
	rep.mu.Lock()
	var oldest *inflight
	for f := range rep.inflight {
		if !f.reported && now.Sub(f.start) > limit && (oldest == nil || f.start.Before(oldest.start)) {
			oldest = f
		}
	}
	if oldest != nil {
		oldest.reported = true
	}
	rep.mu.Unlock()
	if oldest == nil {
		return false
	}
	var dump bytes.Buffer
	if err := pprof.Lookup("goroutine").WriteTo(&dump, 2); err != nil {
		dump.WriteString(err.Error())
	}
	rep.write("stuck", fmt.Sprintf("request in flight for %s", now.Sub(oldest.start).Round(time.Second)), dump.String(), oldest.req)
	return true
}

func (rep *Reporter) write(kind, value, stack string, req Request) {
	rep.mu.Lock()
	defer rep.mu.Unlock()
	rep.seq++
	r := Report{
		ID:        fmt.Sprintf("crash-%06d", rep.seq),
		Kind:      kind,
		Time:      rep.Now(),
		Service:   rep.Service,
		Version:   rep.Version,
		Commit:    rep.Commit,
		GoVersion: runtime.Version(),
		Panic:     value,
		Stack:     stack,
		Request:   req,
	}
	if rep.Logs != nil {
		r.Logs = rep.Logs.Lines()
	}
	// A crash report that can't be written has nowhere else to go.
	_ = json.NewEncoder(rep.w).Encode(r)
}

func requestOf(r *http.Request) Request {
	req := Request{
		Method:  r.Method,
		Path:    r.URL.Path,
		Query:   r.URL.RawQuery,
		Headers: make(map[string]string, len(r.Header)),
	}
	for k, v := range r.Header {
		req.Headers[k] = v[0]
	}
	return req
}

// limitedWriter keeps the first n bytes written to it and drops the rest.
type limitedWriter struct {
	buf *bytes.Buffer
	n   int
}

func (l *limitedWriter) Write(p []byte) (int, error) {
	if room := l.n - l.buf.Len(); room > 0 {
		l.buf.Write(p[:min(len(p), room)])
	}
	return len(p), nil
}

package api

import (
	"errors"
	"net/http"

	"example.com/remind/auth"
	"example.com/remind/share"
)

// listError answers with the status that matches a share error.
func (a *API) listError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, share.ErrNotFound):
		a.fail(w, http.StatusNotFound, "not found")
	case errors.Is(err, share.ErrForbidden):
		a.fail(w, http.StatusForbidden, "forbidden")
	case errors.Is(err, share.ErrInvalid):
		a.fail(w, http.StatusBadRequest, err.Error())
	default:
		a.writeError(w, err)
	}
}

func (a *API) createList(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req struct {
		Name string `json:"name"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	l, err := a.Lists.Create(u.ID, req.Name)
	if err != nil {
		a.listError(w, err)
		return
	}
	a.writeJSON(w, http.StatusCreated, l)
}

func (a *API) listLists(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	a.writeJSON(w, http.StatusOK, map[string]any{"lists": a.Lists.ForUser(u.ID)})
}

// getList returns a list with the reminders on it.
func (a *API) getList(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	l, err := a.Lists.Get(r.PathValue("id"), u.ID)
	if err != nil {
		a.listError(w, err)
		return
	}
	views := make([]reminderView, 0, len(l.Reminders))
	for _, id := range l.Reminders {
		rem, err := a.Store.Get(id)
		if err != nil {
			continue
		}
		views = append(views, viewOf(rem))
	}
	owner, _ := a.Store.User(l.Owner)
	a.writeJSON(w, http.StatusOK, map[string]any{"list": l, "owner": owner.Name, "reminders": views})
}

func (a *API) addMember(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req struct {
		User string `json:"user"`
		Role string `json:"role"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	role, err := share.ParseRole(req.Role)
	if err != nil {
		a.fail(w, http.StatusBadRequest, err.Error())
		return
	}
	if _, err := a.Store.User(req.User); err != nil {
		a.fail(w, http.StatusBadRequest, "no such user")
		return
	}
	id := r.PathValue("id")
	if err := a.Lists.AddMember(id, u.ID, req.User, role); err != nil {
		a.listError(w, err)
		return
	}
	a.Audit.Record(u.ID, "list.member.add", id, req.User+" as "+role.String())
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) removeMember(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	id, member := r.PathValue("id"), r.PathValue("user")
	if err := a.Lists.RemoveMember(id, u.ID, member); err != nil {
		a.listError(w, err)
		return
	}
	a.Audit.Record(u.ID, "list.member.remove", id, member)
	w.WriteHeader(http.StatusNoContent)
}

// addListReminder puts one of the caller's reminders on a list.
func (a *API) addListReminder(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req struct {
		Reminder string `json:"reminder"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	rem, err := a.Store.Get(req.Reminder)
	if err != nil {
		a.writeError(w, err)
		return
	}
	if rem.UserID != u.ID {
		a.fail(w, http.StatusNotFound, "not found")
		return
	}
	if err := a.Lists.AddReminder(r.PathValue("id"), u.ID, rem.ID); err != nil {
		a.listError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) removeListReminder(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	if err := a.Lists.RemoveReminder(r.PathValue("id"), u.ID, r.PathValue("reminder")); err != nil {
		a.listError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) deleteList(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	id := r.PathValue("id")
	if err := a.Lists.Delete(id, u.ID); err != nil {
		a.listError(w, err)
		return
	}
	a.Audit.Record(u.ID, "list.delete", id, "")
	w.WriteHeader(http.StatusNoContent)
}

package api

import (
	"net/http"
	"net/url"
	"regexp"
	"strconv"
	"time"

	"example.com/remind/auth"
	"example.com/remind/internal/must"
	"example.com/remind/notify"
)

func (a *API) me(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	a.writeJSON(w, http.StatusOK, map[string]any{
		"id": u.ID, "name": u.Name, "email": u.Email, "prefs": u.Prefs,
	})
}

func (a *API) updatePrefs(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req struct {
		TZ        string `json:"tz"`
		Channel   string `json:"channel"`
		Webhook   string `json:"webhook"`
		QuietFrom string `json:"quiet_from"` // "22:00"
		QuietTo   string `json:"quiet_to"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	p := *u.Prefs
	if req.TZ != "" {
		p.TZ = req.TZ
	}
	if req.Channel != "" {
		if !notify.ValidChannel(req.Channel) {
			a.fail(w, http.StatusBadRequest, "unknown channel "+strconv.Quote(req.Channel))
			return
		}
		p.Channel = req.Channel
	}
	if req.Webhook != "" {
		if hook, err := url.Parse(req.Webhook); err != nil || hook.Scheme != "https" {
			a.fail(w, http.StatusBadRequest, "webhook must be an https URL")
			return
		}
		p.Webhook = req.Webhook
	}
	for _, t := range []string{req.QuietFrom, req.QuietTo} {
		if t != "" && !clockPattern.MatchString(t) {
			a.fail(w, http.StatusBadRequest, "quiet hours must look like 22:00")
			return
		}
	}
	if req.QuietFrom != "" || req.QuietTo != "" {
		p.QuietFrom, p.QuietTo = req.QuietFrom, req.QuietTo
	}
	if err := a.Store.SetPrefs(u.ID, p); err != nil {
		a.writeError(w, err)
		return
	}
	a.writeJSON(w, http.StatusOK, p)
}

var clockPattern = regexp.MustCompile(`^\d{1,2}:\d{2}$`)

func (a *API) digest(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	days := 7
	if s := r.URL.Query().Get("days"); s != "" {
		n, err := strconv.Atoi(s)
		if err != nil || n < 1 || n > 31 {
			a.fail(w, http.StatusBadRequest, "days must be between 1 and 31")
			return
		}
		days = n
	}
	loc := must.Get(time.LoadLocation(u.Prefs.TZ))
	from := a.Now()
	occ := a.Store.Upcoming(u.ID, from, from.AddDate(0, 0, days))
	d := notify.BuildDigest(from, days, loc, occ)
	if u.Prefs.QuietFrom != "" && u.Prefs.QuietTo != "" {
		d.QuietHours = notify.QuietHours(u.Prefs.QuietFrom, u.Prefs.QuietTo)
	}
	a.writeJSON(w, http.StatusOK, d)
}

// closeAccount deletes the caller's account and reminders.
func (a *API) closeAccount(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	if err := a.Store.DeleteUser(u.ID); err != nil {
		a.writeError(w, err)
		return
	}
	a.Log.Info("account closed", "user", u.ID)
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) export(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	rems := a.Store.List(u.ID, 0, 1000)
	views := make([]reminderView, len(rems))
	for i, rem := range rems {
		views[i] = viewOf(rem)
	}
	w.Header().Set("Content-Disposition", `attachment; filename="reminders.json"`)
	a.writeJSON(w, http.StatusOK, views)
}

func (a *API) stats(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	now := a.Now()
	var open, done, overdue int
	for _, rem := range a.Store.List(u.ID, 0, 1000) {
		switch {
		case rem.Done:
			done++
		case rem.Due.Before(now):
			overdue++
		default:
			open++
		}
	}
	a.writeJSON(w, http.StatusOK, map[string]int{"open": open, "done": done, "overdue": overdue})
}

// Package share lets users share lists of reminders with each other.
package share

import (
	"cmp"
	"errors"
	"fmt"
	"maps"
	"slices"
	"strings"
	"sync"
	"time"
	"unicode/utf8"
)

// Errors callers check for.
var (
	ErrNotFound  = errors.New("share: not found")
	ErrForbidden = errors.New("share: forbidden")
	ErrInvalid   = errors.New("share: invalid")
)

// maxName is the longest list name, in characters.
const maxName = 80

// A Role is what a member may do with a list. Each role may do
// everything the roles below it may.
type Role int

// The roles, from least to most access.
const (
	Viewer Role = iota + 1 // sees the list and its reminders
	Editor                 // also adds reminders and viewers
	Owner                  // also manages members, renames, and deletes
)

// String returns the role's name: "viewer", "editor", or "owner".
func (r Role) String() string {
	switch r {
	case Viewer:
		return "viewer"
	case Editor:
		return "editor"
	case Owner:
		return "owner"
	}
	return fmt.Sprintf("Role(%d)", int(r))
}

// ParseRole returns the role with the given name.
func ParseRole(s string) (Role, error) {
	switch s {
	case "viewer":
		return Viewer, nil
	case "editor":
		return Editor, nil
	case "owner":
		return Owner, nil
	}
	return 0, fmt.Errorf("parse role %q: %w", s, ErrInvalid)
}

// A List is a named set of reminders shared between its members.
type List struct {
	ID        string
	Name      string
	Owner     string          // user ID of the owner, who is also in Members
	Members   map[string]Role // by user ID
	Reminders []string        // reminder IDs, in the order they were added
	Created   time.Time
}

func (l *List) clone() List {
	c := *l
	c.Members = maps.Clone(l.Members)
	c.Reminders = slices.Clone(l.Reminders)
	return c
}

// Lists holds every shared list. Users who are not members of a list
// get ErrNotFound for it; members whose role does not allow an action
// get ErrForbidden. Lists is safe for concurrent use.
type Lists struct {
	now func() time.Time

	mu    sync.RWMutex
	lists map[string]*List
	seq   int
}

// New returns an empty set of lists. now is its clock.
func New(now func() time.Time) *Lists {
	return &Lists{now: now, lists: make(map[string]*List)}
}

// checkName trims space around a list name and checks its length.
func checkName(name string) (string, error) {
	name = strings.TrimSpace(name)
	if n := utf8.RuneCountInString(name); n < 1 || n > maxName {
		return "", fmt.Errorf("name must be 1 to %d characters: %w", maxName, ErrInvalid)
	}
	return name, nil
}

// member returns the list with the given ID and user's role in it.
func (s *Lists) member(id, user string) (*List, Role, error) {
	l, ok := s.lists[id]
	if !ok {
		return nil, 0, ErrNotFound
	}
	role, ok := l.Members[user]
	if !ok {
		return nil, 0, ErrNotFound
	}
	return l, role, nil
}

// require returns the list with the given ID if by's role in it is at
// least need.
func (s *Lists) require(id, by string, need Role) (*List, error) {
	l, role, err := s.member(id, by)
	if err != nil {
		return nil, err
	}
	if role < need {
		return nil, ErrForbidden
	}
	return l, nil
}

// Create makes a new list owned by owner.
func (s *Lists) Create(owner, name string) (List, error) {
	if owner == "" {
		return List{}, fmt.Errorf("create list: no owner: %w", ErrInvalid)
	}
	name, err := checkName(name)
	if err != nil {
		return List{}, fmt.Errorf("create list: %w", err)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seq++
	l := &List{
		ID:      fmt.Sprintf("lst_%04d", s.seq),
		Name:    name,
		Owner:   owner,
		Members: map[string]Role{owner: Owner},
		Created: s.now(),
	}
	s.lists[l.ID] = l
	return l.clone(), nil
}

// Get returns a list for one of its members.
func (s *Lists) Get(id, user string) (List, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	l, _, err := s.member(id, user)
	if err != nil {
		return List{}, fmt.Errorf("get list %s: %w", id, err)
	}
	return l.clone(), nil
}

// ForUser returns the lists user is a member of, sorted by name.
func (s *Lists) ForUser(user string) []List {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []List
	for _, l := range s.lists {
		if _, ok := l.Members[user]; ok {
			out = append(out, l.clone())
		}
	}
	slices.SortFunc(out, func(a, b List) int {
		return cmp.Or(cmp.Compare(a.Name, b.Name), cmp.Compare(a.ID, b.ID))
	})
	return out
}

// AddMember adds user to a list with the given role, or changes the role
// of an existing member. Owners may add anyone; editors may add new
// viewers. A list has one owner: use TransferOwnership to change it.
func (s *Lists) AddMember(id, by, user string, role Role) error {
	switch {
	case user == "":
		return fmt.Errorf("add member to %s: no user: %w", id, ErrInvalid)
	case role == Owner:
		return fmt.Errorf("add member to %s: a list has one owner: %w", id, ErrInvalid)
	case role != Viewer && role != Editor:
		return fmt.Errorf("add member to %s: %v: %w", id, role, ErrInvalid)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	l, byRole, err := s.member(id, by)
	if err != nil {
		return fmt.Errorf("add member to %s: %w", id, err)
	}
	_, exists := l.Members[user]
	switch {
	case byRole == Owner:
	case byRole == Editor && role == Viewer && !exists:
	default:
		return fmt.Errorf("add %s to %s as %v: %w", user, id, role, ErrForbidden)
	}
	if user == l.Owner {
		return fmt.Errorf("add %s to %s: already the owner: %w", user, id, ErrInvalid)
	}
	l.Members[user] = role
	return nil
}

// RemoveMember removes user from a list. Owners may remove anyone but
// themselves, and other members may remove themselves.
func (s *Lists) RemoveMember(id, by, user string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	l, byRole, err := s.member(id, by)
	if err != nil {
		return fmt.Errorf("remove member from %s: %w", id, err)
	}
	switch {
	case user == l.Owner:
		return fmt.Errorf("remove owner from %s: %w", id, ErrForbidden)
	case user != by && byRole != Owner:
		return fmt.Errorf("remove %s from %s: %w", user, id, ErrForbidden)
	}
	if _, ok := l.Members[user]; !ok {
		return fmt.Errorf("remove %s from %s: %w", user, id, ErrNotFound)
	}
	delete(l.Members, user)
	return nil
}

// AddReminder adds a reminder to a list. Adding a reminder already on
// the list does nothing. Editors and owners may add reminders.
func (s *Lists) AddReminder(id, by, reminderID string) error {
	if reminderID == "" {
		return fmt.Errorf("add reminder to %s: no reminder: %w", id, ErrInvalid)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	l, err := s.require(id, by, Editor)
	if err != nil {
		return fmt.Errorf("add reminder to %s: %w", id, err)
	}
	if !slices.Contains(l.Reminders, reminderID) {
		l.Reminders = append(l.Reminders, reminderID)
	}
	return nil
}

// RemoveReminder takes a reminder off a list. Editors and owners may
// remove reminders.
func (s *Lists) RemoveReminder(id, by, reminderID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	l, err := s.require(id, by, Editor)
	if err != nil {
		return fmt.Errorf("remove reminder from %s: %w", id, err)
	}
	i := slices.Index(l.Reminders, reminderID)
	if i < 0 {
		return fmt.Errorf("remove reminder %s from %s: %w", reminderID, id, ErrNotFound)
	}
	l.Reminders = slices.Delete(l.Reminders, i, i+1)
	return nil
}

// Rename changes a list's name. Only the owner may rename a list.
func (s *Lists) Rename(id, by, name string) error {
	name, err := checkName(name)
	if err != nil {
		return fmt.Errorf("rename %s: %w", id, err)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	l, err := s.require(id, by, Owner)
	if err != nil {
		return fmt.Errorf("rename %s: %w", id, err)
	}
	l.Name = name
	return nil
}

// Delete removes a list. Only the owner may delete a list.
func (s *Lists) Delete(id, by string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, err := s.require(id, by, Owner); err != nil {
		return fmt.Errorf("delete list %s: %w", id, err)
	}
	delete(s.lists, id)
	return nil
}

// RemoveUser deletes the lists user owns and takes user off every other
// list, for when an account is closed. It returns how many lists were
// deleted.
func (s *Lists) RemoveUser(user string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for id, l := range s.lists {
		if l.Owner == user {
			delete(s.lists, id)
			n++
			continue
		}
		delete(l.Members, user)
	}
	return n
}

// TransferOwnership makes a member the owner of a list, and the old
// owner an editor. Only the owner may transfer a list.
func (s *Lists) TransferOwnership(id, by, to string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	l, err := s.require(id, by, Owner)
	if err != nil {
		return fmt.Errorf("transfer %s: %w", id, err)
	}
	if to == by {
		return fmt.Errorf("transfer %s to %s: already the owner: %w", id, to, ErrInvalid)
	}
	if _, ok := l.Members[to]; !ok {
		return fmt.Errorf("transfer %s to %s: not a member: %w", id, to, ErrInvalid)
	}
	l.Members[by] = Editor
	l.Members[to] = Owner
	l.Owner = to
	return nil
}

package store

import (
	"bytes"
	"errors"
	"strings"
	"testing"
	"time"

	"example.com/remind/schedule"
)

var t0 = time.Date(2026, 9, 7, 8, 0, 0, 0, time.UTC)

func newStore() *Store {
	return New(func() time.Time { return t0 })
}

func TestCreateGet(t *testing.T) {
	s := newStore()
	r := s.Create("u1", "water the plants", t0.Add(time.Hour), nil)
	got, err := s.Get(r.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Text != "water the plants" || !got.Due.Equal(t0.Add(time.Hour)) {
		t.Errorf("Get = %+v", got)
	}
	if _, err := s.Get("rem_9999"); !errors.Is(err, ErrNotFound) {
		t.Errorf("Get(missing) error = %v, want ErrNotFound", err)
	}
}

func TestCreateRecurring(t *testing.T) {
	s := newStore()
	rule, err := schedule.Parse("every 2h", nil, t0)
	if err != nil {
		t.Fatal(err)
	}
	r := s.Create("u1", "stretch", time.Time{}, rule)
	if want := t0.Add(2 * time.Hour); !r.Due.Equal(want) {
		t.Errorf("Due = %v, want %v", r.Due, want)
	}
	s.MarkSent(r.ID)
	if want := t0.Add(4 * time.Hour); !r.Due.Equal(want) {
		t.Errorf("after MarkSent, Due = %v, want %v", r.Due, want)
	}
}

func TestList(t *testing.T) {
	s := newStore()
	for _, text := range []string{"a", "b", "c"} {
		s.Create("u1", text, t0, nil)
	}
	if got := s.List("u1", 0, 2); len(got) != 2 || got[0].Text != "a" {
		t.Errorf("List(0, 2) = %v", got)
	}
	if got := s.List("u1", 2, 50); len(got) != 1 || got[0].Text != "c" {
		t.Errorf("List(2, 50) = %v", got)
	}
}

func TestDelete(t *testing.T) {
	s := newStore()
	r := s.Create("u1", "a", t0, nil)
	if err := s.Delete(r.ID); err != nil {
		t.Fatal(err)
	}
	if got := s.List("u1", 0, 50); len(got) != 0 {
		t.Errorf("List after Delete = %v", got)
	}
	if err := s.Delete(r.ID); !errors.Is(err, ErrNotFound) {
		t.Errorf("second Delete error = %v, want ErrNotFound", err)
	}
	if err := s.Update(r.ID, func(*Reminder) error { return nil }); !errors.Is(err, ErrNotFound) {
		t.Errorf("Update after Delete error = %v, want ErrNotFound", err)
	}
}

func TestDue(t *testing.T) {
	s := newStore()
	early := s.Create("u1", "early", t0.Add(-time.Hour), nil)
	s.Create("u1", "later", t0.Add(time.Hour), nil)
	got := s.Due(t0)
	if len(got) != 1 || got[0] != early {
		t.Errorf("Due = %v, want [early]", got)
	}
	s.MarkSent(early.ID)
	if got := s.Due(t0); len(got) != 0 {
		t.Errorf("Due after MarkSent = %v, want none", got)
	}
}

func TestUpcoming(t *testing.T) {
	s := newStore()
	rule, err := schedule.Parse("every 1d", nil, t0)
	if err != nil {
		t.Fatal(err)
	}
	s.Create("u1", "daily", time.Time{}, rule)
	s.Create("u1", "once", t0.Add(30*time.Hour), nil)
	got := s.Upcoming("u1", t0, t0.Add(3*24*time.Hour))
	var texts []string
	for _, o := range got {
		texts = append(texts, o.Text)
	}
	if want := "daily once daily"; strings.Join(texts, " ") != want {
		t.Errorf("Upcoming = %v, want %s", texts, want)
	}
}

func TestOnChange(t *testing.T) {
	s := newStore()
	var seen []string
	s.OnChange(func(r *Reminder) { seen = append(seen, r.ID) })
	r := s.Create("u1", "a", t0, nil)
	if err := s.Update(r.ID, func(r *Reminder) error { r.Done = true; return nil }); err != nil {
		t.Fatal(err)
	}
	if len(seen) != 2 {
		t.Errorf("OnChange calls = %v, want 2", seen)
	}
}

func TestUsers(t *testing.T) {
	s := newStore()
	if err := s.AddUser(User{ID: "u1", Name: "Ana", Token: "tok1"}); err != nil {
		t.Fatal(err)
	}
	u, err := s.UserByToken("tok1")
	if err != nil {
		t.Fatal(err)
	}
	if u.Prefs == nil || u.Prefs.Channel != "email" {
		t.Errorf("new user prefs = %+v, want the defaults", u.Prefs)
	}
	if err := s.AddUser(User{ID: "u1"}); !errors.Is(err, ErrConflict) {
		t.Errorf("duplicate AddUser error = %v, want ErrConflict", err)
	}
	n := s.ImportUsers([]User{{ID: "u1"}, {ID: "u2", Name: "Bo", Token: "tok2", Prefs: &Prefs{Channel: "email"}}})
	if n != 1 {
		t.Errorf("ImportUsers added %d, want 1", n)
	}
	if err := s.DeleteUser("u2"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.UserByToken("tok2"); !errors.Is(err, ErrNotFound) {
		t.Errorf("token after DeleteUser error = %v, want ErrNotFound", err)
	}
}

func TestSnapshot(t *testing.T) {
	s := newStore()
	if err := s.AddUser(User{ID: "u1", Name: "Ana", Token: "secret"}); err != nil {
		t.Fatal(err)
	}
	s.Create("u1", "a", t0, nil)
	var buf bytes.Buffer
	if err := s.Snapshot(&buf); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(buf.String(), "secret") {
		t.Error("snapshot contains a token")
	}
	if !strings.Contains(buf.String(), "rem_0001") {
		t.Errorf("snapshot = %s, want the reminder", buf.String())
	}
}

// Package server assembles remind from its parts.
package server

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"time"

	"example.com/remind/api"
	"example.com/remind/audit"
	"example.com/remind/crash"
	"example.com/remind/metrics"
	"example.com/remind/notify"
	"example.com/remind/quota"
	"example.com/remind/search"
	"example.com/remind/share"
	"example.com/remind/store"
)

// Config configures a Server. Zero values get defaults.
type Config struct {
	Version  string
	Commit   string
	Now      func() time.Time               // default time.Now
	Log      io.Writer                      // default io.Discard
	Crashes  io.Writer                      // where crash reports go; default io.Discard
	Users    []store.User                   // users to start with
	Snapshot func() (io.WriteCloser, error) // where admin snapshots go
	// WebhookSecret signs webhook deliveries.
	WebhookSecret []byte
	// RateLimits turns on per-user rate limits.
	RateLimits bool
}

// A Server is a configured remind service.
type Server struct {
	Handler    http.Handler
	Store      *store.Store
	Dispatcher *notify.Dispatcher
	Reporter   *crash.Reporter
	Log        *slog.Logger
}

// New builds a Server.
func New(cfg Config) (*Server, error) {
	if cfg.Now == nil {
		cfg.Now = time.Now
	}
	if cfg.Log == nil {
		cfg.Log = io.Discard
	}
	if cfg.Crashes == nil {
		cfg.Crashes = io.Discard
	}
	ring := crash.NewLogRing(slog.NewTextHandler(cfg.Log, nil), 12, cfg.Now)
	log := slog.New(ring)

	st := store.New(cfg.Now)
	for _, u := range cfg.Users {
		if err := st.AddUser(u); err != nil {
			return nil, fmt.Errorf("server: %w", err)
		}
	}
	d := notify.NewDispatcher(st, log, cfg.Now)

	rep := crash.NewReporter(cfg.Crashes, cfg.Now)
	rep.Version = cfg.Version
	rep.Commit = cfg.Commit
	rep.Logs = ring

	d.SetWebhookSecret(cfg.WebhookSecret)

	reg := metrics.NewRegistry()
	reg.Now = cfg.Now
	a := &api.API{
		Store:    st,
		Notify:   d,
		Lists:    share.New(cfg.Now),
		Search:   search.New(),
		Audit:    audit.New(1000, cfg.Now),
		Metrics:  reg.Handler(),
		Log:      log,
		Now:      cfg.Now,
		Snapshot: cfg.Snapshot,
	}
	if cfg.RateLimits {
		a.Limiter = quota.NewLimiter(cfg.Now)
	}
	return &Server{
		Handler:    rep.Middleware(metrics.Instrument(reg, accessLog(log, cfg.Now, a.Routes()))),
		Store:      st,
		Dispatcher: d,
		Reporter:   rep,
		Log:        log,
	}, nil
}

// Watch writes a crash report for any request in flight longer than
// limit, checking every interval until ctx ends.
func (s *Server) Watch(ctx context.Context, interval, limit time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			s.Reporter.Check(limit)
		}
	}
}

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (w *statusWriter) WriteHeader(status int) {
	w.status = status
	w.ResponseWriter.WriteHeader(status)
}

func accessLog(log *slog.Logger, now func() time.Time, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := now()
		sw := &statusWriter{ResponseWriter: w, status: http.StatusOK}
		next.ServeHTTP(sw, r)
		log.Info("request", "method", r.Method, "path", r.URL.Path, "status", sw.status,
			"dur", now().Sub(start).String(), "ua", r.UserAgent())
	})
}

package store

import (
	"cmp"
	"fmt"
	"slices"
)

// A User owns reminders and authenticates with an API token.
type User struct {
	ID    string
	Name  string
	Email string
	Token string `json:"-"`
	Admin bool
	Plan  string // "free" or "pro"; empty means free
	Prefs *Prefs
}

// Prefs are a user's notification settings.
type Prefs struct {
	TZ      string // IANA zone name; empty means UTC
	Channel string // "email" or "webhook"
	Webhook string // URL for the webhook channel
	Lang    string // language for notifications, such as "pt"; empty means English

	// Quiet hours, as "22:00" and "07:00": reminders due in between wait
	// until the end.
	QuietFrom string
	QuietTo   string
}

// DefaultPrefs returns the settings a new user starts with.
func DefaultPrefs() *Prefs {
	return &Prefs{Channel: "email"}
}

// AddUser adds a user, giving it default preferences if it has none.
func (s *Store) AddUser(u User) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.users[u.ID]; ok {
		return fmt.Errorf("add user %s: %w", u.ID, ErrConflict)
	}
	if u.Prefs == nil {
		u.Prefs = DefaultPrefs()
	}
	s.users[u.ID] = &u
	if u.Token != "" {
		s.tokens[u.Token] = &u
	}
	return nil
}

// ImportUsers adds users in bulk, as exported from another system.
// Existing IDs are skipped. It returns how many users were added.
func (s *Store) ImportUsers(users []User) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for _, u := range users {
		if _, ok := s.users[u.ID]; ok {
			continue
		}
		s.users[u.ID] = &u
		if u.Token != "" {
			s.tokens[u.Token] = &u
		}
		n++
	}
	return n
}

// SetPrefs replaces a user's preferences.
func (s *Store) SetPrefs(id string, p Prefs) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.users[id]
	if !ok {
		return ErrNotFound
	}
	u.Prefs = &p
	return nil
}

// User returns a user by ID.
func (s *Store) User(id string) (*User, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	u, ok := s.users[id]
	if !ok {
		return nil, ErrNotFound
	}
	return u, nil
}

// UserByToken returns the user with the given API token.
func (s *Store) UserByToken(token string) (*User, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	u, ok := s.tokens[token]
	if !ok {
		return nil, ErrNotFound
	}
	return u, nil
}

// DeleteUser removes a user and all of their reminders.
func (s *Store) DeleteUser(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.users[id]
	if !ok {
		return ErrNotFound
	}
	delete(s.users, id)
	delete(s.tokens, u.Token)
	for _, r := range s.byUser[id] {
		r.Deleted = true
		s.changed(r)
	}
	return nil
}

// Users returns all users, sorted by ID.
func (s *Store) Users() []*User {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := make([]*User, 0, len(s.users))
	for _, u := range s.users {
		out = append(out, u)
	}
	slices.SortFunc(out, func(a, b *User) int { return cmp.Compare(a.ID, b.ID) })
	return out
}

