func newClient(t *testing.T) *client {
	t.Helper()
	srv, err := server.New(server.Config{
		Now: func() time.Time { return t0 },
		Users: []store.User{
			{ID: "ana", Name: "Ana", Email: "ana@example.com", Token: "tok-ana"},
