// Package auth authenticates API requests by bearer token.
package auth

import (
	"context"
	"net/http"
	"strings"

	"example.com/remind/store"
)

type userKey struct{}

// Require lets a request through only if it carries a valid API token,
// and makes the token's user available through UserFrom.
func Require(s *store.Store, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u, ok := authenticate(s, r)
		if !ok {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey{}, u)))
	})
}

// RequireAdmin is Require for administrators only.
func RequireAdmin(s *store.Store, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u, ok := authenticate(s, r)
		if !ok {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		if !u.Admin {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey{}, u)))
	})
}

// UserFrom returns the authenticated user, or nil if there is none.
func UserFrom(ctx context.Context) *store.User {
	u, _ := ctx.Value(userKey{}).(*store.User)
	return u
}

func authenticate(s *store.Store, r *http.Request) (*store.User, bool) {
	token, ok := parseBearer(r.Header.Get("Authorization"))
	if !ok {
		return nil, false
	}
	u, err := s.UserByToken(token)
	if err != nil {
		return nil, false
	}
	return u, true
}

// parseBearer extracts the token from "Bearer <token>". A header with
// no token, such as "Bearer" or "Bearer ", does not authenticate.
func parseBearer(h string) (string, bool) {
	token, ok := strings.CutPrefix(h, "Bearer ")
	if !ok || token == "" {
		return "", false
	}
	return token, true
}

// Package notify delivers reminders through each user's chosen channel.
package notify

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"maps"
	"slices"
	"sync"
	"time"

	"example.com/remind/i18n"
	"example.com/remind/store"
	"example.com/remind/webhook"
)

// A Message is one notification.
type Message struct {
	To      *store.User
	Subject string
	Body    string
}

// A Sender delivers messages over one channel.
type Sender interface {
	Send(ctx context.Context, m Message) error
}

// channels lists the channel names users may choose.
var channels = []string{"email", "webhook", "sms"}

// ValidChannel reports whether name is a channel users may choose.
func ValidChannel(name string) bool {
	return slices.Contains(channels, name)
}

// Dispatcher sends due reminders.
type Dispatcher struct {
	store   *store.Store
	senders map[string]Sender
	log     *slog.Logger
	now     func() time.Time

	mu       sync.Mutex
	retries  map[string]int // failed sends per reminder ID
	stop     chan struct{}
	stopOnce sync.Once // makes Stop safe to call more than once
}

// NewDispatcher returns a dispatcher with the email and webhook channels.
func NewDispatcher(s *store.Store, log *slog.Logger, now func() time.Time) *Dispatcher {
	d := &Dispatcher{
		store: s,
		senders: map[string]Sender{
			"email":   emailSender{log: log},
			"webhook": webhookSender{client: &webhook.Client{Log: log, Now: now}, now: now},
		},
		log:     log,
		now:     now,
		retries: make(map[string]int),
		stop:    make(chan struct{}),
	}
	s.OnChange(d.forget)
	return d
}

// SetWebhookSecret sets the key webhook deliveries are signed with.
func (d *Dispatcher) SetWebhookSecret(secret []byte) {
	d.senders["webhook"].(webhookSender).client.Secret = secret
}

// Status is what the admin dashboard shows about deliveries.
type Status struct {
	Retrying int      `json:"retrying"` // reminders whose last send failed
	Channels []string `json:"channels"`
}

// Status reports the dispatcher's current state.
func (d *Dispatcher) Status() Status {
	return Status{Retrying: len(d.retries), Channels: slices.Sorted(maps.Keys(d.senders))}
}

// Run sends due reminders every interval until Stop is called or ctx
// ends.
func (d *Dispatcher) Run(ctx context.Context, interval time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-d.stop:
			return
		case <-t.C:
			d.flush(ctx)
		}
	}
}

// Stop stops Run. Calling Stop again does nothing.
func (d *Dispatcher) Stop() {
	d.stopOnce.Do(func() { close(d.stop) })
}

// flush sends every due reminder once. It holds d.mu so flushes never
// overlap.
func (d *Dispatcher) flush(ctx context.Context) {
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, r := range d.store.Due(d.now()) {
		u, err := d.store.User(r.UserID)
		if err != nil {
			continue
		}
		if err := d.SendNow(ctx, u, r); err != nil {
			d.retries[r.ID]++
			d.log.Warn("notify: send failed", "reminder", r.ID, "attempt", d.retries[r.ID], "err", err)
			continue
		}
		delete(d.retries, r.ID)
		d.store.MarkSent(r.ID)
	}
}

// forget drops retry state for a reminder that changed.
func (d *Dispatcher) forget(r *store.Reminder) {
	d.mu.Lock()
	defer d.mu.Unlock()
	delete(d.retries, r.ID)
}

// SendNow sends one reminder to its user immediately.
func (d *Dispatcher) SendNow(ctx context.Context, u *store.User, r *store.Reminder) error {
	if err := d.senders[u.Prefs.Channel].Send(ctx, message(u, r)); err != nil {
		return fmt.Errorf("send %s: %w", r.ID, err)
	}
	return nil
}

// message renders a reminder in the user's language.
func message(u *store.User, r *store.Reminder) Message {
	lang := u.Prefs.Lang
	return Message{
		To:      u,
		Subject: i18n.Translate(lang, "reminder.subject", 0, map[string]string{"text": Preview(r.Text)}),
		Body:    i18n.Translate(lang, "reminder.body", 0, map[string]string{"name": u.Name, "text": r.Text}),
	}
}

type emailSender struct {
	log *slog.Logger
}

func (s emailSender) Send(_ context.Context, m Message) error {
	// The mail relay picks messages up from the log stream.
	s.log.Info("notify: email queued", "to", m.To.Email, "subject", m.Subject)
	return nil
}

type webhookSender struct {
	client *webhook.Client
	now    func() time.Time
}

func (s webhookSender) Send(ctx context.Context, m Message) error {
	body, err := json.Marshal(map[string]string{"subject": m.Subject, "body": m.Body})
	if err != nil {
		return fmt.Errorf("webhook: %w", err)
	}
	d := &webhook.Delivery{
		ID:      fmt.Sprintf("whd_%d", s.now().UnixNano()),
		URL:     m.To.Prefs.Webhook,
		Event:   "reminder.due",
		Payload: body,
		Created: s.now(),
	}
	if err := s.client.Post(ctx, d); err != nil {
		return fmt.Errorf("webhook to %s: %w", d.URL, err)
	}
	return nil
}

// Package store keeps users and reminders in memory and writes snapshots
// of them to disk.
package store

import (
	"cmp"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"slices"
	"sync"
	"time"

	"example.com/remind/schedule"
)

// Errors callers check for.
var (
	ErrNotFound = errors.New("store: not found")
	ErrConflict = errors.New("store: conflict")
)

// maxOccurrences caps how many times Upcoming expands one recurring
// reminder, so a rule like "every 1m" can't produce millions of entries.
const maxOccurrences = 50

// A Reminder is one reminder. Recurring reminders have a Rule; one-off
// reminders have only Due.
type Reminder struct {
	ID       string
	UserID   string
	Text     string
	Rule     schedule.Rule
	Due      time.Time // the next time it fires
	Done     bool
	Priority int  // 1 (high) to 3 (low); 0 means normal
	Deleted  bool // kept as a tombstone so sync clients see the delete
	Created  time.Time
}

// An Occurrence is one future firing of a reminder.
type Occurrence struct {
	ReminderID string
	Text       string
	At         time.Time
}

// Store holds all users and reminders.
type Store struct {
	now func() time.Time

	mu        sync.RWMutex
	users     map[string]*User // by ID
	tokens    map[string]*User // by API token
	reminders map[string]*Reminder
	byUser    map[string][]*Reminder
	seq       int
	onChange  func(*Reminder)
}

// New returns an empty store. now is its clock.
func New(now func() time.Time) *Store {
	return &Store{
		now:       now,
		users:     make(map[string]*User),
		tokens:    make(map[string]*User),
		reminders: make(map[string]*Reminder),
		byUser:    make(map[string][]*Reminder),
	}
}

// OnChange registers a function called whenever a reminder changes.
func (s *Store) OnChange(f func(*Reminder)) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.onChange = f
}

func (s *Store) changed(r *Reminder) {
	if s.onChange != nil {
		s.onChange(r)
	}
}

// Create adds a reminder for a user. For a recurring reminder, Due is
// computed from its rule.
func (s *Store) Create(userID, text string, due time.Time, rule schedule.Rule) *Reminder {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.now()
	if rule != nil {
		due = rule.Next(now)
	}
	s.seq++
	r := &Reminder{
		ID:      fmt.Sprintf("rem_%04d", s.seq),
		UserID:  userID,
		Text:    text,
		Rule:    rule,
		Due:     due,
		Created: now,
	}
	s.reminders[r.ID] = r
	s.byUser[userID] = append(s.byUser[userID], r)
	s.changed(r)
	return r
}

// Get returns a reminder by ID. Deleted reminders are not returned.
func (s *Store) Get(id string) (*Reminder, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	r, ok := s.reminders[id]
	if !ok || r.Deleted {
		return nil, ErrNotFound
	}
	return r, nil
}

// List returns a page of a user's reminders, oldest first.
func (s *Store) List(userID string, offset, limit int) []*Reminder {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []*Reminder
	for _, r := range s.byUser[userID] {
		if !r.Deleted {
			out = append(out, r)
		}
	}
	end := min(offset+limit, len(out))
	return out[offset:end]
}

// Count returns how many reminders a user has, not counting deleted ones.
func (s *Store) Count(userID string) int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	n := 0
	for _, r := range s.byUser[userID] {
		if !r.Deleted {
			n++
		}
	}
	return n
}

// Update calls f with the reminder locked, then records the change.
func (s *Store) Update(id string, f func(*Reminder) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok || r.Deleted {
		return ErrNotFound
	}
	if err := f(r); err != nil {
		return err
	}
	s.changed(r)
	return nil
}

// Delete marks a reminder deleted, keeping a tombstone.
func (s *Store) Delete(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok || r.Deleted {
		return ErrNotFound
	}
	r.Deleted = true
	s.changed(r)
	return nil
}

// Due returns reminders that are due at or before now and not done.
func (s *Store) Due(now time.Time) []*Reminder {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []*Reminder
	for _, r := range s.reminders {
		if !r.Done && !r.Deleted && !r.Due.After(now) {
			out = append(out, r)
		}
	}
	slices.SortFunc(out, func(a, b *Reminder) int { return a.Due.Compare(b.Due) })
	return out
}

// MarkSent records that a reminder fired: a recurring reminder moves to
// its next time, and a one-off reminder is done.
func (s *Store) MarkSent(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok {
		return
	}
	if r.Rule != nil {
		r.Due = r.Rule.Next(r.Due)
	} else {
		r.Done = true
	}
}

// Upcoming returns the times a user's reminders fire in [from, to),
// sorted by time. Recurring reminders appear once per occurrence.
func (s *Store) Upcoming(userID string, from, to time.Time) []Occurrence {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []Occurrence
	for _, r := range s.byUser[userID] {
		if r.Done || r.Deleted {
			continue
		}
		if r.Rule == nil {
			if !r.Due.Before(from) && r.Due.Before(to) {
				out = append(out, Occurrence{ReminderID: r.ID, Text: r.Text, At: r.Due})
			}
			continue
		}
		t := r.Rule.Next(from)
		for n := 0; !t.IsZero() && t.Before(to) && n < maxOccurrences; n++ {
			out = append(out, Occurrence{ReminderID: r.ID, Text: r.Text, At: t})
			t = r.Rule.Next(t)
		}
	}
	slices.SortStableFunc(out, func(a, b Occurrence) int { return cmp.Compare(a.At.UnixNano(), b.At.UnixNano()) })
	return out
}

// Snapshot writes every user and reminder to w as JSON.
func (s *Store) Snapshot(w io.Writer) error {
	s.mu.RLock()
	defer s.mu.RUnlock()
	type reminder struct {
		*Reminder
		Rule string `json:",omitempty"`
	}
	snap := struct {
		Users     []*User
		Reminders []reminder
	}{}
	for _, u := range s.users {
		snap.Users = append(snap.Users, u)
	}
	slices.SortFunc(snap.Users, func(a, b *User) int { return cmp.Compare(a.ID, b.ID) })
	for _, r := range s.reminders {
		rr := reminder{Reminder: r}
		if r.Rule != nil {
			rr.Rule = r.Rule.String()
		}
		snap.Reminders = append(snap.Reminders, rr)
	}
	slices.SortFunc(snap.Reminders, func(a, b reminder) int { return cmp.Compare(a.ID, b.ID) })
	if err := json.NewEncoder(w).Encode(snap); err != nil {
		return fmt.Errorf("store: snapshot: %w", err)
	}
	return nil
}
